        try self._ensureLoopBoundary(beatCount, (Gp3To5Importer._maxBeatCount), "beat count")
        do {
            var i: Double = 0.0
            while i < beatCount {
                try self.readBeat(track, bar, newVoice)
                i += 1
            }
        }
    }

    /**
     * Attempts to skip a fully empty voice.
     */
    private func _skipEmptyVoice() throws -> Bool {
        let startOfVoice: Double = self.data.position
        let flags: Double = try self.data.readByte()
        var isEmpty: Bool = false
        if (jsAnd(flags, 64)) != 0 {
            let type: Double = try self.data.readByte()
            isEmpty = (jsAnd(type, 2)) == 0
        }
        if !isEmpty {
            self.data.position = startOfVoice
            return false
        }
        self.data.skip(2.0)
        if self._versionNumber >= 500 {
            self.data.skip(2.0)
        }
        return true
    }

    public func readBeat(_ track: Track, _ bar: Bar, _ voice: Voice) throws {
        let newBeat: Beat = Beat()
        let flags: Double = try self.data.readByte()
        if (jsAnd(flags, 1)) != 0 {
            newBeat.dots = 1.0
        }
        if (jsAnd(flags, 64)) != 0 {
            let type: Double = try self.data.readByte()
            newBeat.isEmpty = (jsAnd(type, 2)) == 0
        }
        voice.addBeat(newBeat)
        let duration: Double = try IOHelper.readSInt8(self.data)
        switch duration {
        case -2.0:
            newBeat.duration = Duration.Whole
        case -1.0:
            newBeat.duration = Duration.Half
        case 0.0:
            newBeat.duration = Duration.Quarter
        case 1.0:
            newBeat.duration = Duration.Eighth
        case 2.0:
            newBeat.duration = Duration.Sixteenth
        case 3.0:
            newBeat.duration = Duration.ThirtySecond
        case 4.0:
            newBeat.duration = Duration.SixtyFourth
        default:
            newBeat.duration = Duration.Quarter
        }
        if (jsAnd(flags, 32)) != 0 {
            try newBeat.tupletNumerator = IOHelper.readInt32LE(self.data)
            switch newBeat.tupletNumerator {
            case 1.0:
                newBeat.tupletDenominator = 1.0
            case 3.0:
                newBeat.tupletDenominator = 2.0
            case 5.0, 6.0, 7.0:
                newBeat.tupletDenominator = 4.0
            case 9.0, 10.0, 11.0, 12.0, 13.0:
                newBeat.tupletDenominator = 8.0
            case 2.0, 4.0, 8.0:
                break
            default:
                newBeat.tupletNumerator = 1.0
                newBeat.tupletDenominator = 1.0
            }
        }
        if (jsAnd(flags, 2)) != 0 {
            try self.readChord(newBeat)
        }
        let beatTextAsLyrics: Bool = self.settings.importer.beatTextAsLyrics && track.index != self._lyricsTrack
        if (jsAnd(flags, 4)) != 0 {
            let text: String = try GpBinaryHelpers.gpReadStringIntUnused(self.data, self._stringEncoding, self.settings.importer.maxDecodingBufferSize)
            if beatTextAsLyrics {
                let lyrics: Lyrics = Lyrics()
                lyrics.text = text.trim()
                lyrics.finish(true)
                let beatLyrics: List<String> = List<String>()
                do {
                    var i: Double = lyrics.chunks.length - 1.0
                    while i >= 0 {
                        beatLyrics.push(lyrics.chunks[(i).toInt()])
                        i -= 1
                    }
                }
                self._beatTextChunksByTrack.set(track.index, beatLyrics)
            } else {
                newBeat.text = text
            }
        }
        var allNoteHarmonicType: HarmonicType = HarmonicType.None
        if (jsAnd(flags, 8)) != 0 {
            try allNoteHarmonicType = self.readBeatEffects(newBeat)
        }
        if (jsAnd(flags, 16)) != 0 {
            try self.readMixTableChange(newBeat)
        }
        let stringFlags: Double = try self.data.readByte()
        do {
            var i: Double = 6.0
            while i >= 0 {
                if (jsAnd(stringFlags, jsShl(1, i))) != 0 && 6.0 - i < bar.staff.tuning.length {
                    let note: Note = try self.readNote(track, bar, voice, newBeat, 6.0 - i)
                    if allNoteHarmonicType != HarmonicType.None {
                        note.harmonicType = allNoteHarmonicType
                        note.harmonicValue = ModelUtils.deltaFretToHarmonicValue(note.fret)
                    }
                }
                i -= 1
            }
        }
        if self._versionNumber >= 500 {
            let flags2: Double = try IOHelper.readInt16LE(self.data)
            if (jsAnd(flags2, 1)) != 0 {
                if newBeat.index > 0 {
                    voice.beats[(newBeat.index - 1.0).toInt()].beamingMode = BeatBeamingMode.ForceSplitToNext
                }
            }
            if (jsAnd(flags2, 2)) != 0 {
                newBeat.preferredBeamDirection = BeamDirection.Down
            }
            if (jsAnd(flags2, 4)) != 0 {
                if newBeat.index > 0 {
                    voice.beats[(newBeat.index - 1.0).toInt()].beamingMode = BeatBeamingMode.ForceMergeWithNext
                }
            }
            if (jsAnd(flags2, 8)) != 0 {
                newBeat.preferredBeamDirection = BeamDirection.Up
            }
            if (jsAnd(flags2, 16)) != 0 {
                newBeat.ottava = Ottavia._8va
            }
            if (jsAnd(flags2, 32)) != 0 {
                newBeat.ottava = Ottavia._8vb
            }
            if (jsAnd(flags2, 64)) != 0 {
                newBeat.ottava = Ottavia._15ma
            }
            if (jsAnd(flags2, 256)) != 0 {
                newBeat.ottava = Ottavia._15mb
            }
            if (jsAnd(flags2, 2048)) != 0 {
                let breakSecondaryBeams: Bool = try self.data.readByte() != 0.0
                if newBeat.index > 0 && breakSecondaryBeams {
                    voice.beats[(newBeat.index - 1.0).toInt()].beamingMode = BeatBeamingMode.ForceSplitOnSecondaryToNext
                }
            }
        }
        if try beatTextAsLyrics && !newBeat.isRest && self._beatTextChunksByTrack.has(track.index) && jsNonNull(self._beatTextChunksByTrack.get(track.index)).length > 0 {
            try newBeat.lyrics = List<String>(jsNonNull(jsNonNull(self._beatTextChunksByTrack.get(track.index)).pop()))
        }
    }

    public func readChord(_ beat: Beat) throws {
        let chord: Chord = Chord()
        let chordId: String = ModelUtils.newGuid()
        if self._versionNumber >= 500 {
            self.data.skip(17.0)
            try chord.name = GpBinaryHelpers.gpReadStringByteLength(self.data, 21.0, self._stringEncoding)
            self.data.skip(4.0)
            try chord.firstFret = IOHelper.readInt32LE(self.data)
            do {
                var i: Double = 0.0
                while i < 7 {
                    let fret: Double = try IOHelper.readInt32LE(self.data)
                    if i < beat.voice.bar.staff.tuning.length {
                        chord.strings.push(fret)
                    }
                    i += 1
                }
            }
            let numberOfBarres: Double = try self.data.readByte()
            let barreFrets: Uint8Array = Uint8Array(5.0)
            try self.data.read(barreFrets, 0.0, barreFrets.length)
            do {
                var i: Double = 0.0
                while i < numberOfBarres {
                    chord.barreFrets.push(barreFrets[(i).toInt()])
                    i += 1
                }
            }
            self.data.skip(26.0)
        } else {
            if try self.data.readByte() != 0.0 {
                if self._versionNumber >= 400 {
                    self.data.skip(16.0)
                    try chord.name = GpBinaryHelpers.gpReadStringByteLength(self.data, 21.0, self._stringEncoding)
                    self.data.skip(4.0)
                    try chord.firstFret = IOHelper.readInt32LE(self.data)
                    do {
                        var i: Double = 0.0
                        while i < 7 {
                            let fret: Double = try IOHelper.readInt32LE(self.data)
                            if i < beat.voice.bar.staff.tuning.length {
                                chord.strings.push(fret)
                            }
                            i += 1
                        }
                    }
                    let numberOfBarres: Double = try self.data.readByte()
                    let barreFrets: Uint8Array = Uint8Array(5.0)
                    try self.data.read(barreFrets, 0.0, barreFrets.length)
                    do {
                        var i: Double = 0.0
                        while i < numberOfBarres {
                            chord.barreFrets.push(barreFrets[(i).toInt()])
                            i += 1
                        }
                    }
                    self.data.skip(26.0)
                } else {
                    self.data.skip(25.0)
                    try chord.name = GpBinaryHelpers.gpReadStringByteLength(self.data, 34.0, self._stringEncoding)
                    try chord.firstFret = IOHelper.readInt32LE(self.data)
                    do {
                        var i: Double = 0.0
                        while i < 6 {
                            let fret: Double = try IOHelper.readInt32LE(self.data)
                            if i < beat.voice.bar.staff.tuning.length {
                                chord.strings.push(fret)
                            }
                            i += 1
                        }
                    }
                    self.data.skip(36.0)
                }
            } else {
                let strings: Double = self._versionNumber >= 406 ? 7.0 : 6.0
                try chord.name = GpBinaryHelpers.gpReadStringIntByte(self.data, self._stringEncoding, self.settings.importer.maxDecodingBufferSize)
                try chord.firstFret = IOHelper.readInt32LE(self.data)
                if chord.firstFret > 0 {
                    do {
                        var i: Double = 0.0
                        while i < strings {
                            let fret: Double = try IOHelper.readInt32LE(self.data)
                            if i < beat.voice.bar.staff.tuning.length {
                                chord.strings.push(fret)
                            }
                            i += 1
                        }
                    }
                }
            }
        }
        if TypeHelper.isTruthy(chord.name) {
            beat.chordId = chordId
            beat.voice.bar.staff.addChord(beat.chordId!, chord)
        }
    }

    public func readBeatEffects(_ beat: Beat) throws -> HarmonicType {
        let flags: Double = try self.data.readByte()
        var flags2: Double = 0.0
        if self._versionNumber >= 400 {
            try flags2 = self.data.readByte()
        }
        if (jsAnd(flags, 16)) != 0 {
            beat.fade = FadeType.FadeIn
        }
        if (self._versionNumber < 400 && (jsAnd(flags, 1)) != 0) || (jsAnd(flags, 2)) != 0 {
            beat.vibrato = VibratoType.Slight
        }
        if (jsAnd(flags2, 1)) != 0 {
            beat.rasgueado = Rasgueado.Ii
        }
        if (jsAnd(flags, 32)) != 0 && self._versionNumber >= 400 {
            let slapPop: Double = try IOHelper.readSInt8(self.data)
            switch slapPop {
            case 1.0:
                beat.tap = true
            case 2.0:
                beat.slap = true
            case 3.0:
                beat.pop = true
            default:
                break
            }
        } else if (jsAnd(flags, 32)) != 0 {
            let slapPop: Double = try IOHelper.readSInt8(self.data)
            switch slapPop {
            case 1.0:
                beat.tap = true
            case 2.0:
                beat.slap = true
            case 3.0:
                beat.pop = true
            default:
                break
            }
            self.data.skip(4.0)
        }
        if (jsAnd(flags2, 4)) != 0 {
            try self.readTremoloBarEffect(beat)
        }
        if (jsAnd(flags, 64)) != 0 {
            var strokeUp: Double = 0.0
            var strokeDown: Double = 0.0
            if self._versionNumber < 500 {
                try strokeDown = self.data.readByte()
                try strokeUp = self.data.readByte()
            } else {
                try strokeUp = self.data.readByte()
                try strokeDown = self.data.readByte()
            }
            if strokeUp > 0 {
                beat.brushType = BrushType.BrushUp
                beat.brushDuration = Gp3To5Importer._toStrokeValue(strokeUp)
            } else if strokeDown > 0 {
                beat.brushType = BrushType.BrushDown
                beat.brushDuration = Gp3To5Importer._toStrokeValue(strokeDown)
            }
        }
        if (jsAnd(flags2, 2)) != 0 {
            switch try IOHelper.readSInt8(self.data) {
            case 0.0:
                beat.pickStroke = PickStroke.None
            case 1.0:
                beat.pickStroke = PickStroke.Up
            case 2.0:
                beat.pickStroke = PickStroke.Down
            default:
                break
            }
        }
        if self._versionNumber < 400 {
            if (jsAnd(flags, 4)) != 0 {
                return HarmonicType.Natural
            }
            if (jsAnd(flags, 8)) != 0 {
                return HarmonicType.Artificial
            }
        }
        return HarmonicType.None
    }

    public func readTremoloBarEffect(_ beat: Beat) throws {
        try self.data.readByte()
        try IOHelper.readInt32LE(self.data)
        let pointCount: Double = try IOHelper.readInt32LE(self.data)
        try self._ensureLoopBoundary(pointCount, Gp3To5Importer._maxBendPointCount, "tremolo bar point count")
        if pointCount > 0 {
            do {
                var i: Double = 0.0
                while i < pointCount {
                    let point: BendPoint = BendPoint(0.0, 0.0)
                    try point.offset = IOHelper.readInt32LE(self.data)
                    try point.value = jsOr(IOHelper.readInt32LE(self.data) / Gp3To5Importer._bendStep, 0)
                    try GpBinaryHelpers.gpReadBool(self.data)
                    beat.addWhammyBarPoint(point)
                    i += 1
                }
            }
        }
    }

    private static func _toStrokeValue(_ value: Double) -> Double {
        switch value {
        case 1.0:
            return 30.0
        case 2.0:
            return 30.0
        case 3.0:
            return 60.0
        case 4.0:
            return 120.0
        case 5.0:
            return 240.0
        case 6.0:
            return 480.0
        default:
            return 0.0
        }
    }

    private func _readRseBank() {
        self.data.skip(4.0)
        self.data.skip(4.0)
        self.data.skip(4.0)
        self.data.skip(4.0)
    }

    public func readMixTableChange(_ beat: Beat) throws {
        let tableChange: MixTableChange = MixTableChange()
        try tableChange.instrument = IOHelper.readSInt8(self.data)
        if self._versionNumber >= 500 {
            self._readRseBank()
        }
        try tableChange.volume = IOHelper.readSInt8(self.data)
        try tableChange.balance = IOHelper.readSInt8(self.data)
        let chorus: Double = try IOHelper.readSInt8(self.data)
        let reverb: Double = try IOHelper.readSInt8(self.data)
        let phaser: Double = try IOHelper.readSInt8(self.data)
        let tremolo: Double = try IOHelper.readSInt8(self.data)
        if self._versionNumber >= 500 {
            try tableChange.tempoName = GpBinaryHelpers.gpReadStringIntByte(self.data, self._stringEncoding, self.settings.importer.maxDecodingBufferSize)
        }
        try tableChange.tempo = IOHelper.readInt32LE(self.data)
        if tableChange.volume >= 0 {
            try self.data.readByte()
        }
        if tableChange.balance >= 0 {
            try self.data.readByte()
        }
        if chorus >= 0 {
            try self.data.readByte()
        }
        if reverb >= 0 {
            try self.data.readByte()
        }
        if phaser >= 0 {
            try self.data.readByte()
        }
        if tremolo >= 0 {
            try self.data.readByte()
        }
        if tableChange.tempo >= 0 {
            try tableChange.duration = IOHelper.readSInt8(self.data)
            if self._versionNumber >= 510 {
                try self.data.readByte()
            }
        }
        if self._versionNumber >= 400 {
            try self.data.readByte()
        }
        if self._versionNumber >= 500 {
            let wahType: Double = try IOHelper.readSInt8(self.data)
            if wahType >= 100 {
                beat.wahPedal = WahPedal.Closed
            } else if wahType >= 0 {
                beat.wahPedal = WahPedal.Open
            }
        }
        if self._versionNumber >= 510 {
            try GpBinaryHelpers.gpReadStringIntByte(self.data, self._stringEncoding, self.settings.importer.maxDecodingBufferSize)
            try GpBinaryHelpers.gpReadStringIntByte(self.data, self._stringEncoding, self.settings.importer.maxDecodingBufferSize)
        }
        if tableChange.volume >= 0 {
            let volumeAutomation: Automation = Automation()
            volumeAutomation.isLinear = true
            volumeAutomation.type = AutomationType.Volume
            volumeAutomation.value = tableChange.volume
            beat.automations.push(volumeAutomation)
        }
        if tableChange.balance >= 0 {
            let balanceAutomation: Automation = Automation()
            balanceAutomation.isLinear = true
            balanceAutomation.type = AutomationType.Balance
            balanceAutomation.value = tableChange.balance
            beat.automations.push(balanceAutomation)
        }
        if tableChange.instrument >= 0 {
            let instrumentAutomation: Automation = Automation()
            instrumentAutomation.isLinear = true
            instrumentAutomation.type = AutomationType.Instrument
            instrumentAutomation.value = tableChange.instrument
            beat.automations.push(instrumentAutomation)
        }
        if tableChange.tempo >= 0 {
            let tempoAutomation: Automation = Automation()
            tempoAutomation.isLinear = true
            tempoAutomation.type = AutomationType.Tempo
            tempoAutomation.value = tableChange.tempo
            beat.automations.push(tempoAutomation)
            if !beat.voice.bar.masterBar.tempoAutomations.some({ (a: Automation) -> Bool in
                return a.ratioPosition == tempoAutomation.ratioPosition && a.value == tempoAutomation.value
            }) {
                beat.voice.bar.masterBar.tempoAutomations.push(tempoAutomation)
            }
        }
    }

    public func readNote(_ track: Track, _ bar: Bar, _ voice: Voice, _ beat: Beat, _ stringIndex: Double) throws -> Note {
        let newNote: Note = Note()
        newNote.string = bar.staff.tuning.length - stringIndex
        let flags: Double = try self.data.readByte()
        if (jsAnd(flags, 2)) != 0 {
            newNote.accentuated = AccentuationType.Heavy
        } else if (jsAnd(flags, 64)) != 0 {
            newNote.accentuated = AccentuationType.Normal
        }
        newNote.isGhost = (jsAnd(flags, 4)) != 0
        if (jsAnd(flags, 32)) != 0 {
            let noteType: Double = try self.data.readByte()
            if noteType == 3.0 {
                newNote.isDead = true
            } else if noteType == 2.0 {
                newNote.isTieDestination = true
            }
        }
        if (jsAnd(flags, 1)) != 0 && self._versionNumber < 500 {
            try self.data.readByte()
            try self.data.readByte()
        }
        if (jsAnd(flags, 16)) != 0 {
            let dynamicNumber: Double = try IOHelper.readSInt8(self.data)
            newNote.dynamics = self.toDynamicValue(dynamicNumber)
            beat.dynamics = newNote.dynamics
        }
        if (jsAnd(flags, 32)) != 0 {
            try newNote.fret = IOHelper.readSInt8(self.data)
        }
        if (jsAnd(flags, 128)) != 0 {
            try newNote.leftHandFinger = Fingers.fromValue(IOHelper.readSInt8(self.data))
            try newNote.rightHandFinger = Fingers.fromValue(IOHelper.readSInt8(self.data))
        }
        var swapAccidentals: Bool = false
        if self._versionNumber >= 500 {
            if (jsAnd(flags, 1)) != 0 {
                try newNote.durationPercent = IOHelper.readFloat64BE(self.data)
            }
            let flags2: Double = try self.data.readByte()
            swapAccidentals = (jsAnd(flags2, 2)) != 0
        }
        beat.addNote(newNote)
        if (jsAnd(flags, 8)) != 0 {
            try self.readNoteEffects(track, voice, beat, newNote)
        }
        if bar.staff.isPercussion {
            let midi: Double = try Gp3To5Importer._gp5PercussionInstrumentMap.has(newNote.fret) ? jsNonNull(Gp3To5Importer._gp5PercussionInstrumentMap.get(newNote.fret)) : newNote.fret
            let knownArticulation: InstrumentArticulation? = try PercussionMapper.getArticulationById(midi)
            if knownArticulation != nil {
                newNote.percussionArticulation = bar.staff.track.getOrRegisterPercussionArticulation(knownArticulation!)
            }
            newNote.fret = Number.NaN
        }
        if swapAccidentals {
            let accidental: AccidentalType = try ModelUtils.computeAccidental(bar.keySignature, NoteAccidentalMode.Default, newNote.realValueWithoutHarmonic, false)
            if accidental == AccidentalType.Sharp {
                newNote.accidentalMode = NoteAccidentalMode.ForceFlat
            } else if accidental == AccidentalType.Flat {
                newNote.accidentalMode = NoteAccidentalMode.ForceSharp
            }
        }
        return newNote
    }

    public func toDynamicValue(_ value: Double) -> DynamicValue {
        switch value {
        case 1.0:
            return DynamicValue.PPP
        case 2.0:
            return DynamicValue.PP
        case 3.0:
            return DynamicValue.P
        case 4.0:
            return DynamicValue.MP
        case 5.0:
            return DynamicValue.MF
        case 6.0:
            return DynamicValue.F
        case 7.0:
            return DynamicValue.FF
        case 8.0:
            return DynamicValue.FFF
        default:
            return DynamicValue.F
        }
    }

    public func readNoteEffects(_ _track: Track, _ voice: Voice, _ beat: Beat, _ note: Note) throws {
        let flags: Double = try self.data.readByte()
        var flags2: Double = 0.0
        if self._versionNumber >= 400 {
            try flags2 = self.data.readByte()
        }
        if (jsAnd(flags, 1)) != 0 {
            try self.readBend(note)
        }
        if (jsAnd(flags, 16)) != 0 {
            try self.readGrace(voice, note)
        }
        if (jsAnd(flags2, 4)) != 0 {
            try self.readTremoloPicking(beat)
        }
        if (jsAnd(flags2, 8)) != 0 {
            try self.readSlide(note)
        } else if self._versionNumber < 400 {
            if (jsAnd(flags, 4)) != 0 {
                note.slideOutType = SlideOutType.Shift
            }
        }
        if (jsAnd(flags2, 16)) != 0 {
            try self.readArtificialHarmonic(note)
        }
        if (jsAnd(flags2, 32)) != 0 {
            try self.readTrill(note)
        }
        note.isLetRing = (jsAnd(flags, 8)) != 0
        note.isHammerPullOrigin = (jsAnd(flags, 2)) != 0
        if (jsAnd(flags2, 64)) != 0 {
            note.vibrato = VibratoType.Slight
        }
        note.isPalmMute = (jsAnd(flags2, 2)) != 0
        note.isStaccato = (jsAnd(flags2, 1)) != 0
    }

    private static let _bendStep: Double = 25.0

    public func readBend(_ note: Note) throws {
        try self.data.readByte()
        try IOHelper.readInt32LE(self.data)
        let pointCount: Double = try IOHelper.readInt32LE(self.data)
        try self._ensureLoopBoundary(pointCount, Gp3To5Importer._maxBendPointCount, "note bend point count")
        if pointCount > 0 {
            do {
                var i: Double = 0.0
                while i < pointCount {
                    let point: BendPoint = BendPoint(0.0, 0.0)
                    try point.offset = IOHelper.readInt32LE(self.data)
                    try point.value = jsOr(IOHelper.readInt32LE(self.data) / Gp3To5Importer._bendStep, 0)
                    try GpBinaryHelpers.gpReadBool(self.data)
                    note.addBendPoint(point)
                    i += 1
                }
            }
        }
    }

    public func readGrace(_ voice: Voice, _ note: Note) throws {
        let graceBeat: Beat = Beat()
        let graceNote: Note = Note()
        graceNote.string = note.string
        try graceNote.fret = IOHelper.readSInt8(self.data)
        graceBeat.duration = Duration.ThirtySecond
        try graceBeat.dynamics = self.toDynamicValue(IOHelper.readSInt8(self.data))
        let transition: Double = try IOHelper.readSInt8(self.data)
        switch transition {
        case 0.0:
            break
        case 1.0:
            graceNote.slideOutType = SlideOutType.Legato
            graceNote.slideTarget = note
        case 2.0:
            break
        case 3.0:
            graceNote.isHammerPullOrigin = true
        default:
            break
        }
        graceNote.dynamics = graceBeat.dynamics
        self.data.skip(1.0)
        if self._versionNumber < 500 {
            graceBeat.graceType = GraceType.BeforeBeat
        } else {
            let flags: Double = try self.data.readByte()
            graceNote.isDead = (jsAnd(flags, 1)) != 0
            graceBeat.graceType = (jsAnd(flags, 2)) != 0 ? GraceType.OnBeat : GraceType.BeforeBeat
        }
        voice.addGraceBeat(graceBeat)
        graceBeat.addNote(graceNote)
    }

    public func readTremoloPicking(_ beat: Beat) throws {
        let effect: TremoloPickingEffect = TremoloPickingEffect()
        beat.tremoloPicking = effect
        try effect.marks = self.data.readByte()
    }

    public func readSlide(_ note: Note) throws {
        if self._versionNumber >= 500 {
            let type: Double = try IOHelper.readSInt8(self.data)
            if (jsAnd(type, 1)) != 0 {
                note.slideOutType = SlideOutType.Shift
            } else if (jsAnd(type, 2)) != 0 {
                note.slideOutType = SlideOutType.Legato
            } else if (jsAnd(type, 4)) != 0 {
                note.slideOutType = SlideOutType.OutDown
            } else if (jsAnd(type, 8)) != 0 {
                note.slideOutType = SlideOutType.OutUp
            }
            if (jsAnd(type, 16)) != 0 {
                note.slideInType = SlideInType.IntoFromBelow
            } else if (jsAnd(type, 32)) != 0 {
                note.slideInType = SlideInType.IntoFromAbove
            }
        } else {
            let type: Double = try IOHelper.readSInt8(self.data)
            switch type {
            case 1.0:
                note.slideOutType = SlideOutType.Shift
            case 2.0:
                note.slideOutType = SlideOutType.Legato
            case 3.0:
                note.slideOutType = SlideOutType.OutDown
            case 4.0:
                note.slideOutType = SlideOutType.OutUp
            case -1.0:
                note.slideInType = SlideInType.IntoFromBelow
            case -2.0:
                note.slideInType = SlideInType.IntoFromAbove
            default:
                break
            }
        }
    }

    public func readArtificialHarmonic(_ note: Note) throws {
        let type: Double = try self.data.readByte()
        if self._versionNumber >= 500 {
            switch type {
            case 1.0:
                note.harmonicType = HarmonicType.Natural
                note.harmonicValue = ModelUtils.deltaFretToHarmonicValue(note.fret)
            case 2.0:
                let harmonicTone: Double = try self.data.readByte()
                var harmonicKey: Double = try self.data.readByte()
                if harmonicKey == 255.0 {
                    harmonicKey = -1.0
                }
                let harmonicOctaveOffset: Double = try self.data.readByte()
                let harmonicPitch: Double = harmonicTone + harmonicKey
                let playedPitch: Double = (note.fret + note.stringTuning).truncatingRemainder(dividingBy: 12.0)
                var targetHarmonic: Double = harmonicPitch + harmonicOctaveOffset * 12.0
                if targetHarmonic < playedPitch {
                    targetHarmonic += 12.0
                }
                let deltaFrets: Double = targetHarmonic - playedPitch
                note.harmonicType = HarmonicType.Artificial
                note.harmonicValue = ModelUtils.deltaFretToHarmonicValue(deltaFrets)
            case 3.0:
                note.harmonicType = HarmonicType.Tap
                try note.harmonicValue = ModelUtils.deltaFretToHarmonicValue(self.data.readByte())
            case 4.0:
                note.harmonicType = HarmonicType.Pinch
                note.harmonicValue = ModelUtils.deltaFretToHarmonicValue(12.0)
            case 5.0:
                note.harmonicType = HarmonicType.Semi
                note.harmonicValue = ModelUtils.deltaFretToHarmonicValue(12.0)
            default:
                break
            }
        } else if self._versionNumber >= 400 {
            switch type {
            case 1.0:
                note.harmonicType = HarmonicType.Natural
                note.harmonicValue = ModelUtils.deltaFretToHarmonicValue(note.fret)
            case 3.0:
                note.harmonicType = HarmonicType.Tap
                note.harmonicValue = ModelUtils.deltaFretToHarmonicValue(12.0)
            case 4.0:
                note.harmonicType = HarmonicType.Pinch
                note.harmonicValue = ModelUtils.deltaFretToHarmonicValue(12.0)
            case 5.0:
                note.harmonicType = HarmonicType.Semi
                note.harmonicValue = ModelUtils.deltaFretToHarmonicValue(12.0)
            case 15.0:
                note.harmonicType = HarmonicType.Artificial
                note.harmonicValue = ModelUtils.deltaFretToHarmonicValue(5.0)
            case 17.0:
                note.harmonicType = HarmonicType.Artificial
                note.harmonicValue = ModelUtils.deltaFretToHarmonicValue(7.0)
            case 22.0:
                note.harmonicType = HarmonicType.Artificial
                note.harmonicValue = ModelUtils.deltaFretToHarmonicValue(12.0)
            default:
                break
            }
        }
    }

    public func readTrill(_ note: Note) throws {
        try note.trillValue = self.data.readByte() + note.stringTuning
        switch try self.data.readByte() {
        case 1.0:
            note.trillSpeed = Duration.Sixteenth
        case 2.0:
            note.trillSpeed = Duration.ThirtySecond
        case 3.0:
            note.trillSpeed = Duration.SixtyFourth
        default:
            break
        }
    }

    public override init() {
        super.init()
    }
}

internal final class GpBinaryHelpers {
    public static func gpReadColor(_ data: any IReadable, _ readAlpha: Bool = false) throws -> Color {
        let r: Double = try data.readByte()
        let g: Double = try data.readByte()
        let b: Double = try data.readByte()
        var a: Double = 255.0
        if readAlpha {
            try a = data.readByte()
        } else {
            data.skip(1.0)
        }
        return Color(r, g, b, a)
    }

    public static func gpReadBool(_ data: any IReadable) throws -> Bool {
        return try data.readByte() != 0.0
    }

    /**
     * Skips an integer (4byte) and reads a string using
     * a bytesize
     */
    public static func gpReadStringIntUnused(_ data: any IReadable, _ encoding: String, _ maxDecodingBufferSize: Double) throws -> String {
        data.skip(4.0)
        return try GpBinaryHelpers.gpReadString(data, data.readByte(), encoding, maxDecodingBufferSize)
    }

    /**
     * Reads an integer as size, and then the string itself
     */
    public static func gpReadStringInt(_ data: any IReadable, _ encoding: String, _ maxDecodingBufferSize: Double) throws -> String {
        return try GpBinaryHelpers.gpReadString(data, IOHelper.readInt32LE(data), encoding, maxDecodingBufferSize)
    }

    /**
     * Reads an integer as size, skips a byte and reads the string itself
     */
    public static func gpReadStringIntByte(_ data: any IReadable, _ encoding: String, _ maxDecodingBufferSize: Double) throws -> String {
        let length: Double = try IOHelper.readInt32LE(data) - 1.0
        try data.readByte()
        return try GpBinaryHelpers.gpReadString(data, length, encoding, maxDecodingBufferSize)
    }

    public static func gpReadString(_ data: any IReadable, _ length: Double, _ encoding: String, _ maxDecodingBufferSize: Double) throws -> String {
        if length > maxDecodingBufferSize {
            throw OverflowError("Detected string exceeding maxDecodingBufferSize at offset \((data.position).toTemplate())")
        }
        let b: Uint8Array = Uint8Array(length)
        try data.read(b, 0.0, b.length)
        return IOHelper.toString(b, encoding)
    }

    public static func gpWriteString(_ data: any IWriteable, _ s: String) {
        let encoded: Uint8Array = IOHelper.stringToBytes(s)
        data.writeByte(s.length)
        data.write(encoded, 0.0, encoded.length)
    }

    /**
     * Reads a byte as size and the string itself.
     * Additionally it is ensured the specified amount of bytes is read.
     */
    public static func gpReadStringByteLength(_ data: any IReadable, _ length: Double, _ encoding: String) throws -> String {
        let stringLength: Double = try data.readByte()
        let fieldBytes: Uint8Array = Uint8Array(length)
        try data.read((fieldBytes as! Uint8Array), 0.0, length)
        let effectiveLength: Double = Math.min(stringLength, length)
        return IOHelper.toString(fieldBytes.subarray(0.0, effectiveLength), encoding)
    }

    public init() {}
}

/**
 * A mixtablechange describes several track changes.
 */
internal final class MixTableChange {
    public var volume: Double = -1.0

    public var balance: Double = -1.0

    public var instrument: Double = -1.0

    public var tempoName: String = ""

    public var tempo: Double = -1.0

    public var duration: Double = -1.0

    public init() {}
}

/**
 * The midi channel information
 */
internal final class Gp3To5MidiChannelInfo: IRecord {
    public var program: Double = 0.0

    public var volume: Double = 0.0

    public var balance: Double = 0.0

    public var chorus: Double = 0.0

    public var reverb: Double = 0.0

    public var phase: Double = 0.0

    public var tremolo: Double = 0.0

    public init(program: Double, volume: Double, balance: Double, chorus: Double, reverb: Double, phase: Double, tremolo: Double) {
        self.program = program
        self.volume = volume
        self.balance = balance
        self.chorus = chorus
        self.reverb = reverb
        self.phase = phase
        self.tremolo = tremolo
    }
}
